PAIRS.push(...[["FPTS / GIẢI PHÁP PCCC", "FPTS / FIRE PROTECTION"], ["Hệ thống báo cháy tự động", "Automatic fire alarm systems"], ["Phát hiện sớm, cảnh báo kịp thời với tủ trung tâm, đầu báo khói, đầu báo nhiệt và thiết bị báo cháy đồng bộ.", "Early detection and timely alerts with coordinated control panels, smoke detectors, heat detectors and alarm devices."], ["Xem thiết bị báo cháy", "View fire alarm equipment"], ["Chữa cháy khí cho không gian trọng yếu", "Gas suppression for critical spaces"], ["Giải pháp chữa cháy bằng khí cho phòng máy chủ, trung tâm dữ liệu và phòng điện, được tư vấn theo đặc thù từng công trình.", "Gas fire suppression solutions for server rooms, data centers and electrical rooms, tailored to each project."], ["Khám phá giải pháp", "Explore solutions"], ["Thi công – bảo trì hệ thống PCCC", "Fire protection installation & maintenance"], ["Đồng hành từ lắp đặt, chạy thử và bàn giao đến kiểm tra, bảo dưỡng và hỗ trợ vận hành hệ thống.", "Support from installation, testing and handover to inspections, maintenance and system operation."], ["Xem dịch vụ PCCC", "View fire protection services"], ["Danh mục thiết bị chữa cháy, hệ thống báo cháy, chữa cháy bằng khí và thiết bị đo lường – phát hiện khí của FPTS.", "FPTS fire equipment, fire alarm systems, gas suppression and gas detection and measurement equipment."], ["Thiết bị phòng cháy chữa cháy", "Fire protection equipment"]]);
